const icons={home:'<path d="M3 11.5 12 4l9 7.5V21a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',dumbbell:'<path d="M6 7v10M3 9v6m15-8v10m3-8v6M6 12h12"/>',chart:'<path d="M4 20V10m6 10V4m6 16v-7m4 7H2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 18 6-6-6-6"/>',spark:'<path d="m12 2 1.6 5.4L19 9l-5.4 1.6L12 16l-1.6-5.4L5 9l5.4-1.6zM19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z"/>',trend:'<path d="m3 17 6-6 4 4 8-9"/><path d="M15 6h6v6"/>',trophy:'<path d="M8 4h8v4a4 4 0 0 1-8 0zM6 6H3v1a4 4 0 0 0 4 4m11-5h3v1a4 4 0 0 1-4 4M12 12v5m-4 4h8m-6-4h4"/>',close:'<path d="M6 6l12 12M18 6 6 18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-8h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',reset:'<path d="M4 12a8 8 0 1 0 2.34-5.66L4 8.68M4 4v4.68h4.68"/>'};
document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[el.dataset.icon]}</svg>`});
const switchView=id=>{document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})};
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
document.querySelector('.theme-toggle').addEventListener('click',e=>{const root=document.documentElement;const light=root.dataset.theme==='light';root.dataset.theme=light?'dark':'light';e.currentTarget.setAttribute('aria-pressed',String(!light))});
document.querySelectorAll('.step').forEach(b=>b.addEventListener('click',()=>{const el=document.getElementById(b.dataset.target);let v=parseFloat(el.textContent.replace(',','.'))+Number(b.dataset.delta);v=Math.max(0,v);el.textContent=(b.dataset.target==='weight'?v.toFixed(1).replace('.0',''):v).toString().replace('.',',')}));
document.querySelector('.complete-set').addEventListener('click',()=>{const toast=document.querySelector('.toast');toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400);document.querySelector('.set-tabs .active').classList.add('complete');document.querySelector('.set-tabs .active').classList.remove('active');document.querySelectorAll('.set-tabs button')[2].classList.add('active')});
document.querySelectorAll('.range-tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.range-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));
document.querySelectorAll('.timer-actions button').forEach(b=>b.addEventListener('click',()=>{const el=document.getElementById('timer');const [m,s]=el.textContent.split(':').map(Number);const t=Math.max(0,m*60+s+Number(b.dataset.time));el.textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`}));
